```javascript
function solve(input) {
  const ids = Object.values(input.refs);
  const activeHeads = input.commits.filter(c => ids.includes(c.id) && c.validity === 'active');
  const experienceQuarantines = new Set();

  for (const commit of activeHeads) {
    if (commit.experienceId in input.refs) {
      const ref = input.refs[commit.experienceId];
      if (ref && !ids.includes(ref)) {
        experienceQuarantines.add(commit.experienceId);
      }
    }
  }

  const activeCurrentHeads = activeHeads.filter(head => !experienceQuarantines.has(head.experienceId));

  return activeCurrentHeads.map(head => head.id).sort();
}
